func unansweredRegions(result *decisionlog.Result) []decisionlog.RegionStatus {
	var out []decisionlog.RegionStatus
	for _, status := range result.Regions {
		if status.State != decisionlog.RegionOK {
			out = append(out, status)
		}
	}
	return out
}

insight_filter.text:
func (current view) globalInsights() []insights.Insight {
	if current.Evaluation == nil {
		return nil
	}
	merged := slices.Clone(current.Evaluation.Insights)
	insights.Rank(merged)
	return merged
}

func (current view) globalCounts() insights.Counts {
	return insights.Count(current.globalInsights())
}

// filteredInsights applies the insights page's severity and region filters.
func (current view) filteredInsights() []insights.Insight {
	severities := current.State.list("severity")
	regions := current.State.regionFilter()
	var out []insights.Insight
	for _, insight := range current.globalInsights() {
		if len(severities) > 0 && !slices.Contains(severities, string(insight.Severity)) {
			continue
		}
		if len(regions) > 0 && !slices.Contains(regions, insight.Region) {
			continue
		}
		out = append(out, insight)
	}
	return out
}

func (current view) regionInsights(region string) []insights.Insight {
	var out []insights.Insight
	for _, insight := range current.globalInsights() {
		if insight.Region == region {
			out = append(out, insight)
		}
	}
	return out
}

timeline.text:
func (current view) decisionTimeline(decisions []decisionlog.Decision, byActor bool) chartSpec {
	spec := chartSpec{Kind: "timeline", Start: current.Now.Add(-current.State.Range.Duration).UnixMilli(),
		End: current.Now.UnixMilli()}
	lanes := map[string]bool{}
	for _, decision := range decisions {
		lane := upper(decision.Region)
		if byActor {
			lane = decision.Actor.Slice
		}
		lanes[lane] = true
		spec.Items = append(spec.Items, timelineItem{Time: decision.Time.UnixMilli(), Lane: lane,
			Label: decision.Summary, Status: decisionStatus(decision.Status),
			Detail: kindLabel(decision.Kind) + " · " + decision.Actor.Slice + " · " + statusLabel(decision.Status),
			Href:   current.State.link("/decisions", "id", decision.ID)})
		if decision.Time.UnixMilli() < spec.Start {
			spec.Start = decision.Time.UnixMilli()
		}
	}
	spec.Lanes = slices.Sorted(func(yield func(string) bool) {
		for lane := range lanes {
			if !yield(lane) {
				return
			}
		}
	})
	if len(spec.Items) == 0 {
		switch current.decisionCoverage() {
		case coverageMissing:
			spec.Empty = "No decision journal is attached on this member."
		case coverageFailed:
			spec.Empty = "The decision timeline is unavailable right now: the journal query failed."
		case coveragePartial:
			spec.Empty = "No decisions found, but part of the history could not be searched."
		default:
			spec.Empty = "No decisions were recorded since " + formatTime(time.UnixMilli(spec.Start)) + "."
		}
	}
	return spec
}

insight_evidence.text:
func (current view) insightChart(insight insights.Insight) (chartSpec, bool) {
	var fallback *chartSpec
	for _, evidence := range insight.Evidence {
		spec, ok := current.evidenceChart(insight, evidence)
		if !ok {
			continue
		}
		if evidence.Threshold != nil {
			return spec, true
		}
		if fallback == nil {
			fallback = &spec
		}
	}
	if fallback == nil {
		return chartSpec{}, false
	}
	return *fallback, true
}

// evidenceChart charts an evidence metric over the view's range with its
// threshold, when the metric is in the history store.
func (current view) evidenceChart(insight insights.Insight, evidence insights.Evidence) (chartSpec, bool) {
	if evidence.Metric == "" || insight.Region != current.localRegion() {
		return chartSpec{}, false
	}
	nameBy := "member"
	for name := range evidence.Labels {
		nameBy = name
		break
	}
	series := current.historyRange(evidence.Metric, evidence.Labels, nameBy, false)
	if evidence.Unit == perMinute {
		// Per-minute evidence is a rate of cumulative counters summed over
		// their series (operations), as the rule computed it.
		series = scaleSeries(sumSeries(evidence.Label+" per minute",
			current.historyRange(evidence.Metric, evidence.Labels, nameBy, true)), 60)
	}
	if len(series) == 0 {
		return chartSpec{}, false
	}
	unit := "count"
	switch evidence.Unit {
	case "ratio", "percent":
		unit = "percent"
	case "bytes":
		unit = "bytes"
	case "seconds", "s":
		unit = "seconds"
	}
	spec := current.lineChart("area", unit, series, "")
	spec.Series = spec.Series[:min(len(spec.Series), 4)]
	for index := range spec.Series {
		spec.Series[index].Status = severityStatus(insight.Severity)
	}
	if evidence.Threshold != nil {
		spec.Thresholds = []chartThreshold{{Value: *evidence.Threshold, Label: "threshold " + evidenceThreshold(evidence),
			Status: severityStatus(insight.Severity)}}
	}
	return spec, true
}

// perMinute is the evidence unit of counter rates per minute.
const perMinute = "per min"

// scaleSeries multiplies every point by factor.
func scaleSeries(series []chartSeries, factor float64) []chartSeries {
	for _, one := range series {
		for index := range one.Points {
			one.Points[index][1] = round(one.Points[index][1] * factor)
		}
	}
	return series
}

insight_identity_quiet.text:
func (current view) insightRegions() []string {
	seen := map[string]bool{}
	var regions []string
	for _, region := range current.Global {
		if !seen[region.Cell] {
			seen[region.Cell] = true
			regions = append(regions, region.Cell)
		}
	}
	for _, insight := range current.globalInsights() {
		if !seen[insight.Region] {
			seen[insight.Region] = true
			regions = append(regions, insight.Region)
		}
	}
	return regions
}

// insightID identifies an insight across regions: keys are only unique
// within the region whose engine raised them.
func insightID(insight insights.Insight) string { return insight.Key }

// insightLink opens one insight on the insights page. It lists every region,
// so the insight is shown whatever region is selected.
func (current view) insightLink(insight insights.Insight) string {
	return insightHref(current.State, insight)
}

// insightHref is insightLink for a bare state, as toasts have one.
func insightHref(state uiState, insight insights.Insight) string {
	return state.link("/insights", "id", insightID(insight), "region", allRegions) + "#insight-" + insightID(insight)
}

// quietText is the insights page's empty state: an all-clear only when the
// evaluation ran and nothing is open anywhere.
func (current view) quietText() string {
	open := len(current.globalInsights())
	// A new engine returns an empty evaluation with a zero time until its
	// first pass: that is no evaluation either.
	evaluated := current.Evaluation != nil && !current.Evaluation.At.IsZero()
	unobserved := current.unobservedRegions()
	switch {
	case open > 0:
		return "No insight matches these filters; " + itoa(open) + " are open with other filters."
	case !evaluated && len(current.Global) == 0:
		return "Insights are unavailable on this member: no evaluation has run, so nothing can be ruled out."
	case !evaluated:
		return "Nothing is reported by the other regions, but this region's insights are unavailable, so nothing can be ruled out here."
	case len(unobserved) > 0:
		return "Nothing is open in the regions that answered, but " + strings.ToUpper(strings.Join(unobserved, ", ")) +
			" could not be observed, so nothing can be ruled out there."
	case len(current.Evaluation.Unavailable) > 0:
		return "Nothing is open, but some rules had no input on the last evaluation (listed alongside), so they could not fire."
	default:
		return "Nothing needs attention. Every rule is quiet."
	}
}

// unobservedRegions lists the remote regions whose rollup is missing or
// stale, so their insights cannot be read.
func (current view) unobservedRegions() []string {
	var out []string
	for _, region := range current.Global {
		if region.Cell != current.localRegion() && (region.Rollup == nil || region.Stale) {
			out = append(out, region.Cell)
		}
	}
	return out
}

// foreign returns region when it is not this member's, so a link into that
// region's entity selects it.
func (current view) foreign(region string) string {
	if region == current.localRegion() {
		return ""
	}
	return region
}

regional_tiles.text:
func (current view) regionKPIs() []kpi {
	readiness := "ready"
	if !current.Ready {
		readiness = "not ready"
	}
	tiles := []kpi{{Label: "Readiness", Value: readiness, Sub: "this member: " + current.memberName(),
		Status: boolStatus(current.Ready), Href: current.State.link("/region")}}
	missing := current.missing()
	sub := "all expected members answer"
	if len(missing) > 0 {
		sub = itoa(len(missing)) + " missing: " + joinWords(missing)
	}
	tiles = append(tiles, kpi{Label: "Members answering", Value: itoa(len(current.members())), Sub: sub,
		Status: boolStatus(len(missing) == 0),
		Spark:  sparkValues(current.historyRange(observability.HistMembersAnswering, nil, "", false)),
		Href:   current.State.link("/members")})
	if lease := current.authority(); lease != nil {
		tiles = append(tiles, kpi{Label: "Authority lease", Value: orDash(lease.OwnerID),
			Sub: "epoch " + itoa(lease.Epoch) + " · revision " + itoa(lease.Revision), Status: boolStatus(lease.Ready),
			Spark: sparkValues(current.historyRange(observability.HistAuthorityEpoch, nil, "", false)),
			Href:  current.State.link("/decisions", "kind", "leader_changed")})
	}
	if leader := current.metaLeader(); leader != "" {
		tiles = append(tiles, kpi{Label: "JetStream meta leader", Value: leader, Sub: "raft metadata leader",
			Status: "ok", Href: current.State.link("/nats")})
	}
	if placement := current.placement(); placement != nil {
		partitions := 0
		for _, database := range placement.Databases {
			if !database.Terminal {
				partitions++
			}
		}
		tiles = append(tiles, kpi{Label: "Managed TerraBase partitions", Value: itoa(partitions),
			Sub: counts(placement.StageCounts), Status: "info",
			// Active partitions have their own history, separate from seats.
			Spark: sparkValues(current.historyRange(observability.HistDatabases, nil, "", false)),
			Href:  current.State.link("/terrabase")})
	}
	cpu := current.historyRange(observability.HistCPUUtilization, nil, "member", false)
	if average := averageSeries("cpu", cpu); average != nil {
		value, _ := lastValue(average)
		tiles = append(tiles, kpi{Label: "CPU (mean)", Value: percent(value), Sub: itoa(len(cpu)) + " members",
			Status: ratioStatus(value), Spark: sparkValues(average), Href: current.State.link("/members")})
	}
	memory := current.historyRange(observability.HistMemoryRatio, nil, "member", false)
	if average := averageSeries("memory", memory); average != nil {
		value, _ := lastValue(average)
		tiles = append(tiles, kpi{Label: "Memory (mean)", Value: percent(value), Sub: "used of total",
			Status: ratioStatus(value), Spark: sparkValues(average), Href: current.State.link("/members")})
	}
	if reporter := current.natsReporter(); reporter != nil {
		used := storeUsed(reporter.NATS)
		tiles = append(tiles, kpi{Label: "JetStream store", Value: percent(used),
			Sub: formatBytes(reporter.NATS.StoreUsedBytes) + " used", Status: ratioStatus(used),
			Href: current.State.link("/nats")})
	}
	return tiles
}

readiness.text:
// readinessRow is one member's readiness in the region readiness card.
type readinessRow struct {
	Member  string
	Role    string
	Ready   bool
	Missing bool
	Checks  []observability.CheckResult
}

// readiness lists every answering member's readiness checks, as each member
// evaluated them, then the expected members that did not answer. Without a
// cell-wide view it is this member's own checks.
func (current view) readiness() []readinessRow {
	var rows []readinessRow
	for _, member := range current.members() {
		checks, ready := member.Checks, member.Ready
		if current.Local != nil && member.Member == current.Local.Member && len(current.Checks) > 0 {
			// This member's checks were just evaluated for this render.
			checks, ready = current.Checks, current.Ready
		}
		rows = append(rows, readinessRow{Member: member.Member, Role: member.Role, Ready: ready, Checks: checks})
	}
	if len(rows) == 0 && len(current.Checks) > 0 {
		rows = append(rows, readinessRow{Member: current.memberName(), Ready: current.Ready, Checks: current.Checks})
	}
	for _, name := range current.missing() {
		rows = append(rows, readinessRow{Member: name, Missing: true})
	}
	return rows
}

history_charts.text:
// JSON renders the spec for a data-spec attribute.
func (spec chartSpec) JSON() string {
	data, err := json.Marshal(spec)
	if err != nil {
		return `{"kind":"line","empty":"chart unavailable"}`
	}
	return string(data)
}

func float(value float64) *float64 { return &value }

// historyRange reads every series of metric matching labels over the view's
// range and names each series by the label nameBy. A missing store or no
// data returns nil.
func (current view) historyRange(metric string, labels map[string]string, nameBy string, rate bool) []chartSeries {
	if current.Journal == nil || current.Journal.History == nil {
		return nil
	}
	result := current.Journal.History.Range(observability.HistoryQuery{Metric: metric, Labels: labels,
		Start: current.Now.Add(-current.State.Range.Duration), End: current.Now, Rate: rate, MaxSeries: 64})
	return historyChartSeries(result, metric, nameBy)
}

func historyChartSeries(result observability.HistoryResult, metric, nameBy string) []chartSeries {
	series := make([]chartSeries, 0, len(result.Series))
	for _, found := range result.Series {
		if len(found.Points) == 0 {
			continue
		}
		name := seriesName(found.Labels, nameBy)
		if name == "" {
			name = metric
		}
		points := make([][2]float64, 0, len(found.Points))
		for _, point := range found.Points {
			value := point.Value
			if metric == observability.HistNATSRouteRTT {
				value = point.Max
			}
			if math.IsNaN(value) || math.IsInf(value, 0) {
				continue
			}
			if metric != observability.HistNATSRouteRTT {
				value = round(value)
			}
			points = append(points, [2]float64{float64(point.Time.UnixMilli()), value})
		}
		series = append(series, chartSeries{Name: name, Points: points})
	}
	slices.SortFunc(series, func(left, right chartSeries) int { return cmp.Compare(left.Name, right.Name) })
	return series
}

// seriesName names a series by one label, or by several comma-separated
// labels joined with " / " (consumers are only unique within their stream).
func seriesName(labels map[string]string, nameBy string) string {
	if !strings.Contains(nameBy, ",") {
		return labels[nameBy]
	}
	var parts []string
	for name := range strings.SplitSeq(nameBy, ",") {
		if value := labels[name]; value != "" {
			parts = append(parts, value)
		}
	}
	return strings.Join(parts, " / ")
}

// sumSeries adds series point by point on their shared timestamps.
func sumSeries(name string, series []chartSeries) []chartSeries {
	if len(series) == 0 {
		return nil
	}
	totals := map[float64]float64{}
	for _, one := range series {
		for _, point := range one.Points {
			totals[point[0]] += point[1]
		}
	}
	points := make([][2]float64, 0, len(totals))
	for _, at := range slices.Sorted(maps.Keys(totals)) {
		points = append(points, [2]float64{at, round(totals[at])})
	}
	return []chartSeries{{Name: name, Points: points}}

spark.text:
// sparkValues returns the values of the first series for a sparkline.
func sparkValues(series []chartSeries) string {
	if len(series) == 0 {
		return ""
	}
	points := series[0].Points
	// A sparkline needs no more than about 60 points.
	step := max(1, len(points)/60)
	parts := make([]string, 0, len(points)/step+1)
	for index := 0; index < len(points); index += step {
		parts = append(parts, formatFloat(points[index][1], 4))
	}
	return strings.Join(parts, ",")
}

line_heatmap.text:
// lineChart builds a time-series chart over the view's range.
func (current view) lineChart(kind, unit string, series []chartSeries, empty string) chartSpec {
	spec := chartSpec{Kind: kind, Unit: unit, Series: series, Start: current.Now.Add(-current.State.Range.Duration).UnixMilli(),
		End: current.Now.UnixMilli(), Click: current.State.link("/events") + eventsAtSeparator(current.State.link("/events"))}
	if len(series) == 0 {
		spec.Empty = empty
	}
	return spec
}

func eventsAtSeparator(link string) string {
	if strings.Contains(link, "?") {
		return "&at="
	}
	return "?at="
}

// heatColumns is how many time columns a heatmap has.
const heatColumns = 90

// heatmap builds a rows x time heatmap from per-row series.
func (current view) heatmap(unit string, series []chartSeries, empty string) chartSpec {
	spec := chartSpec{Kind: "heatmap", Unit: unit, Start: current.Now.Add(-current.State.Range.Duration).UnixMilli(),
		End: current.Now.UnixMilli()}
	// Average each row into equal columns across the range, at most
	// heatColumns and never finer than the samples (the history tier's
	// resolution), so cells tile without gaps when sampling is continuous.
	spec.Step = max((spec.End-spec.Start)/heatColumns, sampleSpacing(series), 1)
	columns := max((spec.End-spec.Start+spec.Step-1)/spec.Step, 1)
	for row, one := range series {
		spec.Categories = append(spec.Categories, one.Name)
		sums := map[int64]float64{}
		counts := map[int64]float64{}
		for _, point := range one.Points {
			at := int64(point[0])
			if at < spec.Start || at > spec.End {
				continue
			}
			// The range includes its end; a sample exactly at End belongs
			// to the last column.
			column := min((at-spec.Start)/spec.Step, columns-1)
			sums[column] += point[1]
			counts[column]++
		}
		for _, column := range slices.Sorted(maps.Keys(sums)) {
			spec.Heat = append(spec.Heat, [3]float64{float64(spec.Start + column*spec.Step), float64(row),
				round(sums[column] / counts[column])})
		}
	}
	if len(spec.Heat) == 0 {
		spec.Empty = empty
	}
	return spec
}

// sampleSpacing is the median gap in milliseconds between consecutive points
// of the series, zero without two points.
func sampleSpacing(series []chartSeries) int64 {
	var gaps []int64
	for _, one := range series {
		for index := 1; index < len(one.Points); index++ {
			if gap := int64(one.Points[index][0] - one.Points[index-1][0]); gap > 0 {
				gaps = append(gaps, gap)
			}
		}
	}
	if len(gaps) == 0 {
		return 0
	}
	slices.Sort(gaps)
	return gaps[len(gaps)/2]
}

resource_nodes.text:
func (current view) resourcesForNode(node regionview.Node, local bool) *regionview.ResourceView {
	if node.Resources != nil {
		return node.Resources
	}
	if !local {
		return new(regionview.ResourceView)
	}
	var history observability.HistorySource
	if current.Journal != nil {
		history = current.Journal.History
	}
	return regionview.CollectResources(node, history, current.Now)
}

func (current view) resourceNodes() []regionview.Node {
	for _, summary := range current.topologySummaries() {
		if summary.Region != current.localRegion() {
			continue
		}
		nodes := slices.Clone(summary.Nodes)
		for index := range nodes {
			nodes[index].Resources = current.resourcesForNode(nodes[index], true)
		}
		return nodes
	}
	return nil
}

node_history.text:
// nodeHistory names authenticated whole-node series by the granted node.
func (current view) nodeHistory(metric, nameBy string) []chartSeries {
	var series []chartSeries
	for _, node := range current.resourceNodes() {
		if host := current.State.param("host"); host != "" && host != node.Name {
			continue
		}
		if current.Page.slug == "host" && node.Name != current.Path["h"] {
			continue
		}
		for _, one := range current.historyRange(metric, map[string]string{"member": strings.ToLower(node.Name)}, nameBy, false) {
			if nameBy == "" {
				one.Name = node.Name
			} else {
				one.Name = node.Name + " " + one.Name
			}
			series = append(series, one)
		}
	}
	return series
}

resource_warnings.text:
func (current view) capacityWarning(resources *regionview.ResourceView) string {
	for _, reading := range []*regionview.Reading{resources.MemoryBytes, resources.MemoryUsedBytes} {
		if reading != nil && !reading.Fresh(current.Now) {
			return "Capacity includes stale measurements; inspect the filesystem table for freshness."
		}
	}
	for _, filesystem := range resources.Filesystems {
		if filesystem.SizeBytes != nil && !filesystem.SizeBytes.Fresh(current.Now) || filesystem.UsedBytes != nil && !filesystem.UsedBytes.Fresh(current.Now) {
			return "Capacity includes stale measurements; inspect the filesystem table for freshness."
		}
	}
	return ""
}

topology_sources.text:
// topologySummaries is this region's summary, or this member's own members
// before the summary is loaded. Other regions are not summarized here.
func (current view) topologySummaries() []regionview.Summary {
	if current.LocalSummary != nil {
		return []regionview.Summary{*current.LocalSummary}
	}
	summary := regionview.Summary{Region: current.localRegion(), Local: true, Reach: decisionlog.RegionOK,
		Quorum: regionview.Quorum{Missing: current.missing()}}
	for _, member := range current.members() {
		summary.Members = append(summary.Members, regionview.Member{Name: member.Member, Role: member.Role,
			Ready: member.Ready, Version: member.BuildVersion, MetaLeader: member.NATS != nil && member.NATS.IsMetaLeader})
	}
	return []regionview.Summary{summary}
}

