disk_tree.text:
func (current view) filesystemTree() chartSpec {
	spec := chartSpec{Kind: "treemap", Unit: "bytes"}
	for _, host := range current.resourceNodes() {
		if warning := current.capacityWarning(host.Resources); warning != "" {
			spec.Warning = warning
		}
		node := treeNode{Name: host.Name, Href: current.State.hostLink(current.localRegion(), host.Name)}
		for _, filesystem := range host.Resources.Filesystems {
			if filesystem.SizeBytes == nil {
				continue
			}
			node.Children = append(node.Children, treeNode{Name: cmp.Or(filesystem.Role, filesystem.Path), Value: filesystem.SizeBytes.Value,
				Status: current.readingStatus(filesystem.UsedRatio)})
			node.Value += filesystem.SizeBytes.Value
		}
		if len(node.Children) > 0 {
			spec.Tree = append(spec.Tree, node)
		}
	}
	if len(spec.Tree) == 0 {
		spec.Empty = "No filesystem was observed."
	}
	return spec
}

resource_collection.text:
func CollectResources(node Node, history observability.HistorySource, now time.Time) *ResourceView {
	resources := new(ResourceView)
	received := resources.latest(history, observability.HistHostReceivedAt, node.Name, now)
	if received == nil || received.Value <= 0 || received.Value > float64(now.UnixMilli()) {
		return resources
	}
	resources.batchAt = received.ObservedAt
	resources.ObservedAt = time.UnixMilli(int64(received.Value)).UTC()
	if incomplete := resources.latest(history, observability.HistHostFSIncomplete, node.Name, now); incomplete != nil && incomplete.Value == 1 {
		resources.Incomplete = true
	}
	resources.CPUCores = resources.latest(history, observability.HistHostCPUCores, node.Name, now)
	resources.CPU = resources.latest(history, observability.HistHostCPUUtilization, node.Name, now)
	resources.MemoryBytes = resources.latest(history, observability.HistHostMemoryTotal, node.Name, now)
	resources.Memory = resources.latest(history, observability.HistHostMemoryRatio, node.Name, now)
	resources.Disk = resources.latest(history, observability.HistHostDiskRatio, node.Name, now)
	if resources.MemoryBytes != nil && resources.Memory != nil && resources.MemoryBytes.ObservedAt.Equal(resources.Memory.ObservedAt) {
		resources.MemoryUsedBytes = &Reading{Value: resources.MemoryBytes.Value * resources.Memory.Value, ObservedAt: resources.Memory.ObservedAt}
	}
	resources.filesystems(history, node.Name, now)
	return resources
}

func (resources *ResourceView) latest(history observability.HistorySource, metric, member string, now time.Time) *Reading {
	result := resources.query(history, metric, member, now)
	var reading *Reading
	for _, series := range result.Series {
		if latest := latestReading(series.Points, now); latest != nil && (reading == nil || latest.ObservedAt.After(reading.ObservedAt)) {
			reading = latest
		}
	}
	if reading != nil && reading.Value == 0 && (metric == observability.HistHostCPUCores || metric == observability.HistHostMemoryTotal) {
		return nil
	}
	if reading != nil && metric != observability.HistHostReceivedAt {
		if !reading.ObservedAt.Equal(resources.batchAt) {
			return nil
		}
		reading.ObservedAt = resources.ObservedAt
	}
	return reading
}

func (resources *ResourceView) query(history observability.HistorySource, metric, member string, now time.Time) observability.HistoryResult {
	if history == nil {
		return observability.HistoryResult{}
	}
	result := history.Range(observability.HistoryQuery{Metric: metric, Labels: map[string]string{"member": strings.ToLower(member)},
		Start: now.Add(-time.Hour), End: now, Tier: observability.TierRaw})
	resources.Pending = resources.Pending || result.Pending
	resources.Incomplete = resources.Incomplete || result.Incomplete || result.Truncated
	return result
}

func latestReading(points []observability.Point, now time.Time) *Reading {
	var reading *Reading
	for _, point := range points {
		if math.IsNaN(point.Value) || math.IsInf(point.Value, 0) || point.Value < 0 || point.Time.After(now) {
			continue
		}
		if reading == nil || point.Time.After(reading.ObservedAt) {
			reading = &Reading{Value: point.Value, ObservedAt: point.Time}
		}
	}
	return reading
}

func (resources *ResourceView) filesystems(history observability.HistorySource, member string, now time.Time) {
	type identity struct {
		role, path, device string
	}
	entries := map[identity]*Filesystem{}
	for _, metric := range []string{observability.HistHostFSSize, observability.HistHostFSUsed, observability.HistHostFSRatio,
		observability.HistHostFSFiles, observability.HistHostFSFilesFree} {
		for _, series := range resources.query(history, metric, member, now).Series {
			reading := latestReading(series.Points, now)
			if reading == nil || !reading.ObservedAt.Equal(resources.batchAt) {
				continue
			}
			reading.ObservedAt = resources.ObservedAt
			key := identity{role: series.Labels["role"], path: series.Labels["path"], device: series.Labels["device"]}
			entry := entries[key]
			if entry == nil {
				entry = &Filesystem{Role: key.role, Path: key.path, Device: key.device}
				entries[key] = entry
			}
			switch metric {
			case observability.HistHostFSSize:
				if reading.Value > 0 {
					entry.SizeBytes = reading
				}
			case observability.HistHostFSUsed:
				entry.UsedBytes = reading
			case observability.HistHostFSRatio:
				entry.UsedRatio = reading
			case observability.HistHostFSFiles:
				entry.Files = reading
			case observability.HistHostFSFilesFree:
				entry.FilesFree = reading
			}
		}
	}
	devices := map[string]int{}
	for _, key := range slices.SortedFunc(maps.Keys(entries), func(left, right identity) int {
		return cmp.Or(cmp.Compare(left.role, right.role), cmp.Compare(left.path, right.path), cmp.Compare(left.device, right.device))
	}) {
		entry := entries[key]
		if entry.Device != "" && entry.Device != "0" {
			if index, found := devices[entry.Device]; found {
				resources.Filesystems[index].Role += ", " + entry.Role
				continue
			}
			devices[entry.Device] = len(resources.Filesystems)
		}
		resources.Filesystems = append(resources.Filesystems, *entry)
	}
}

release_coverage.text:
func (current view) releases() []releaseView {
	coverage := current.decisionCoverage()
	byID := map[string]*releaseView{}
	lanes := map[string]map[string]map[string]*releaseStep{}
	// Oldest first, so a later decision for the same step wins.
	decisions := slices.Clone(current.decisions())
	slices.Reverse(decisions)
	for index := range decisions {
		decision := &decisions[index]
		id, name := releaseID(*decision)
		stage := releaseStage(*decision)
		if id == "" || stage == "" {
			continue
		}
		release := byID[id]
		if release == nil {
			release = &releaseView{ID: id, Name: name, Version: releaseVersion(*decision, id), First: decision.Time}
			byID[id] = release
			lanes[id] = map[string]map[string]*releaseStep{}
		}
		if version := decision.Attrs["version"]; version != "" {
			release.Version = version
		}
		if (decision.Kind == decisionlog.KindReleaseAdmitted || decision.Kind == decisionlog.KindUpgradeStarted) &&
			(release.Started.IsZero() || decision.Time.Before(release.Started)) {
			release.Started = decision.Time
		}
		release.Last = decision.Time
		if lanes[id][decision.Region] == nil {
			lanes[id][decision.Region] = map[string]*releaseStep{}
		}
		steps := lanes[id][decision.Region]
		step := steps[stage]
		if step == nil {
			step = &releaseStep{Stage: stage}
			steps[stage] = step
		}
		step.Count++
		step.Decision = decision
		step.Status = decisionStatus(decision.Status)
		step.Label = kindLabel(decision.Kind)
		switch decision.Kind {
		case decisionlog.KindReleaseAdmitted:
			step.Label = cmp.Or(decision.Attrs["delegation"], "admitted")
			// Admission checks fencing, known-bad digests and attempts,
			// not CI: the qualified step shows only explicit evidence.
			if qualification := decision.Attrs["qualification"]; qualification != "" {
				steps["qualified"] = &releaseStep{Stage: "qualified", Decision: decision, Count: 1,
					Status: qualificationStatus(qualification), Label: qualification}
			}
		case decisionlog.KindBatchPromoted:
			step.Label = "batch " + cmp.Or(decision.Attrs["batch"], strconv.Itoa(step.Count))
			if total := decision.Attrs["batches"]; total != "" {
				step.Label += " of " + total
			}
		case decisionlog.KindRollback:
			// A rollback is journaled when it starts and again when the
			// previous version is restored; only the latter is done.
			step.Label, step.Status = "rolling back", "serious"
			if decision.Status == decisionlog.StatusRolledBack {
				step.Label = "rolled back"
			}
			release.Reason = cmp.Or(decision.Reason, decision.Summary)
		case decisionlog.KindRolloutCompleted:
			step.Label = "complete"
		case decisionlog.KindHeld, decisionlog.KindFrozen:
			if aborted(*decision) {
				step.Label, step.Status = "aborted", "bad"
				release.Reason = cmp.Or(decision.Reason, decision.Summary)
				break
			}
			step.Label, step.Status = kindLabel(decision.Kind), "warn"
			if release.Reason == "" {
				release.Reason = cmp.Or(decision.Reason, decision.Summary)
			}
		case decisionlog.KindHoldCleared:
			step.Label = "soak passed"
		}
	}
	out := make([]releaseView, 0, len(byID))
	for id, release := range byID {
		complete, rolledBack, rollingBack, abortedLanes, running := 0, 0, 0, 0, 0
		for _, region := range current.orderRegions(slices.Collect(maps.Keys(lanes[id]))) {
			steps := lanes[id][region]
			lane := releaseLane{Region: region}
			for _, stage := range releaseStages {
				if step := steps[stage]; step != nil {
					lane.Steps = append(lane.Steps, *step)
				} else {
					lane.Steps = append(lane.Steps, releaseStep{Stage: stage})
				}
			}
			release.Lanes = append(release.Lanes, lane)
			switch outcome := steps["outcome"]; {
			case outcome != nil && outcome.Decision.Kind == decisionlog.KindRollback &&
				outcome.Decision.Status == decisionlog.StatusRolledBack:
				rolledBack++
			case outcome != nil && outcome.Decision.Kind == decisionlog.KindRollback:
				rollingBack++
			case outcome != nil && aborted(*outcome.Decision):
				abortedLanes++
			case outcome != nil:
				complete++
			default:
				running++
			}
		}
		release.Partial = coverage != coverageComplete
		unseen := 0
		for _, region := range current.Global {
			if lanes[id][region.Cell] == nil {
				unseen++
			}
		}
		// The window is the decision query's (releaseHistory), not the
		// release's whole life: a region without a lane may have finished
		// it earlier.
		switch {
		case rollingBack > 0:
			release.Status, release.Label = "serious", "rolling back in "+itoa(rollingBack)+" region(s)"
		case rolledBack > 0:
			release.Status, release.Label = "serious", "rolled back in "+itoa(rolledBack)+" region(s)"
		case abortedLanes > 0:
			release.Status, release.Label = "bad", "aborted in "+itoa(abortedLanes)+" region(s)"
		case running == 0 && release.Partial:
			// A region that did not answer may still be rolling out (or
			// may have rolled back): completion covers observed regions.
			release.Status, release.Label = "warn", "complete in "+itoa(complete)+" observed region(s); history partial"
		case running == 0 && unseen > 0:
			release.Status, release.Label = "ok", "complete in "+itoa(complete)+" region(s); "+itoa(unseen)+
				" with no activity in the queried window"
		case running == 0:
			release.Status, release.Label = "ok", "complete everywhere"
		default:
			release.Status, release.Label = "run", "in progress: "+itoa(complete)+" of "+itoa(len(release.Lanes))+" regions complete"
			if release.Partial {
				release.Label += "; history partial"
			}
		}
		out = append(out, *release)
	}
	slices.SortFunc(out, func(left, right releaseView) int {
		return cmp.Or(right.Last.Compare(left.Last), cmp.Compare(left.ID, right.ID))
	})
	return out
}

