func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

// HistoryMetrics is the history store's metric set.
var HistoryMetrics = metrics.NewSet()

var (
	historyDropped = HistoryMetrics.NewCounter(MetricPrefix + "history_series_dropped_total")
	historySamples = HistoryMetrics.NewCounter(MetricPrefix + "history_samples_total")
)

func seriesKey(metric string, labels []Label) string {
	pairs := make([]string, 0, len(labels)*2)
	for _, label := range labels {
		pairs = append(pairs, label.Name, label.Value)
	}
	return Series(metric, pairs...)
}

func sortedLabels(labels []Label) []Label {
	labels = slices.Clone(labels)
	slices.SortFunc(labels, func(left, right Label) int { return cmp.Compare(left.Name, right.Name) })
	return labels
}

func (history *History) newSeries(metric string, labels []Label, counter bool) *series {
	interval := history.config.Interval
	return &series{metric: metric, labels: labels, counter: counter, tiers: map[string]*tier{
		TierRaw: newTier(0, rawRetention, interval),
		Tier1m:  newTier(time.Minute, oneMinuteRetention, interval),
		Tier5m:  newTier(5*time.Minute, fiveMinuteRetention, interval),
		Tier1h:  newTier(time.Hour, HistoryRetention, interval),
	}}
}

// Append stores one batch of samples taken at the same time. NaN and
// infinite values are skipped.
func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

history_range.text:
func TierFor(start, now time.Time) string {
	age := now.Sub(start)
	switch {
	case age <= rawRetention:
		return TierRaw
	case age <= oneMinuteRetention:
		return Tier1m
	case age <= fiveMinuteRetention:
		return Tier5m
	default:
		return Tier1h
	}
}

// Range returns matching series' points in [Start, End], oldest first.
func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

global_fixture.text:
func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

global_regions.text:
func (v *View) listed() []string {
	var others []string
	if v.regions != nil {
		for _, raw := range v.regions() {
			cell := normalize(raw)
			if cell == "" || cell == v.local || slices.Contains(others, cell) {
				continue
			}
			others = append(others, cell)
		}
	}
	slices.Sort(others)
	if v.local == "" {
		return others
	}
	return append([]string{v.local}, others...)
}

// region reads one listed cell. Callers hold mu.
func (v *View) region(cell string) Region {
	r := v.rollups[cell]
	return Region{
		Cell:   cell,
		Rollup: r,
		Stale:  r != nil && v.now().Sub(r.ObservedAt) > StaleAfter,
	}
}

global_validate.text:
func validate(r Rollup, now time.Time) error {
	if r.Version != Version {
		return fmt.Errorf("rollup version %d, want %d", r.Version, Version)
	}
	if token, err := protocol.RegionToken(r.Cell); err != nil || token != r.Cell {
		return fmt.Errorf("rollup cell %q is not a region token", r.Cell)
	}
	if r.ObservedAt.IsZero() || r.ObservedAt.After(now.Add(time.Minute)) {
		return fmt.Errorf("rollup observed_at %s is outside the clock window", r.ObservedAt)
	}
	return nil
}

// normalize returns the region token of cell, or "" when cell is not one.
func normalize(cell string) string {
	token, err := protocol.RegionToken(cell)
	if err != nil {
		return ""
	}
	return token
}

entity_id.text:
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

query_match.text:
func (query Query) Normalized() Query {
	if query.Limit <= 0 {
		query.Limit = DefaultQueryLimit
	}
	query.Limit = min(query.Limit, MaxQueryLimit)
	query.Regions = slices.Clone(query.Regions)
	for index, region := range query.Regions {
		query.Regions[index] = strings.ToLower(region)
	}
	query.Subject = strings.ToLower(query.Subject)
	return query
}

// Matches reports whether a decision satisfies every filter of a normalized
// query.
func (query Query) Matches(decision Decision) bool {
	if len(query.Regions) > 0 && !slices.Contains(query.Regions, decision.Region) {
		return false
	}
	if len(query.Kinds) > 0 && !slices.Contains(query.Kinds, decision.Kind) {
		return false
	}
	if len(query.Actors) > 0 && !slices.ContainsFunc(query.Actors, func(actor string) bool {
		return actor == decision.Actor.Slice || actor == decision.Actor.Slice+"/"+decision.Actor.Member
	}) {
		return false
	}
	if query.SubjectKind != "" && query.SubjectKind != decision.Subject.Kind {
		return false
	}
	if query.SubjectID != "" && query.SubjectID != decision.Subject.ID {
		return false
	}
	if query.Subject != "" && !containsFold(decision.Subject.ID, query.Subject) &&
		!containsFold(decision.Subject.Name, query.Subject) && !containsFold(decision.Summary, query.Subject) {
		return false
	}
	if len(query.Statuses) > 0 && !slices.Contains(query.Statuses, decision.Status) {
		return false
	}
	if query.ParentID != "" && query.ParentID != decision.ParentID {
		return false
	}
	if !query.Since.IsZero() && decision.Time.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && !decision.Time.Before(query.Until) {
		return false
	}
	return true
}

query_chain.text:
func BuildChain(decisions []Decision, id string) (Chain, bool) {
	byID := make(map[string]Decision, len(decisions))
	children := map[string][]string{}
	for _, decision := range decisions {
		byID[decision.ID] = decision
		if decision.ParentID != "" {
			children[decision.ParentID] = append(children[decision.ParentID], decision.ID)
		}
	}
	current, ok := byID[id]
	if !ok {
		return Chain{}, false
	}
	seen := map[string]bool{current.ID: true}
	for current.ParentID != "" {
		parent, found := byID[current.ParentID]
		if !found || seen[parent.ID] {
			break
		}
		seen[parent.ID] = true
		current = parent
	}
	chain := Chain{Root: current}
	visited := map[string]bool{}
	queue := []string{current.ID}
	// The walk is bounded by the input; only the returned list is capped,
	// after Latest is known.
	for len(queue) > 0 {
		next := queue[0]
		queue = queue[1:]
		if visited[next] {
			continue
		}
		visited[next] = true
		chain.Decisions = append(chain.Decisions, byID[next])
		queue = append(queue, children[next]...)
	}
	slices.SortStableFunc(chain.Decisions, func(left, right Decision) int {
		if order := left.Time.Compare(right.Time); order != 0 {
			return order
		}
		return cmp.Compare(left.ID, right.ID)
	})
	chain.Latest = chain.Decisions[len(chain.Decisions)-1]
	if len(chain.Decisions) > MaxQueryLimit {
		chain.Truncated = true
		kept := make([]Decision, 0, MaxQueryLimit)
		newest := chain.Decisions[len(chain.Decisions)-(MaxQueryLimit-2):]
		for _, decision := range chain.Decisions[:len(chain.Decisions)-len(newest)] {
			if decision.ID == chain.Root.ID || decision.ID == id {
				kept = append(kept, decision)
			}
		}
		chain.Decisions = append(kept, newest...)
	}
	return chain, true
}

insight_rank.text:
func Rank(insights []Insight) {
	slices.SortStableFunc(insights, func(left, right Insight) int {
		if order := cmp.Compare(right.Severity.Rank(), left.Severity.Rank()); order != 0 {
			return order
		}
		if order := cmp.Compare(right.Score, left.Score); order != 0 {
			return order
		}
		if order := left.FirstSeen.Compare(right.FirstSeen); order != 0 {
			return order
		}
		return cmp.Compare(left.Key, right.Key)
	})
}

